class Solution {
    public int longestArithSeqLength(int[] nums){
        List<Map<Integer,Integer>> dp=new ArrayList<>();
        int answer=2;
        for(int i=0;i<nums.length;i++){
            dp.add(new HashMap<>());
            for(int j=0;j<i;j++){
                int difference=nums[i]-nums[j];
                int length=dp.get(j).getOrDefault(difference,1)+1;
                dp.get(i).merge(difference,length,Math::max);
                answer=Math.max(answer,length);
            }
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun longestArithSeqLength(nums:IntArray):Int{
        val dp=List(nums.size){
            mutableMapOf<Int,Int>()
        };
        var answer=2;
        for(i in nums.indices)for(j in 0 until i){
            val difference=nums[i]-nums[j];
            val length=(dp[j][difference]?:1)+1;
            dp[i][difference]=maxOf(dp[i][difference]?:0,length);
            answer=maxOf(answer,length)
        };
        return answer
    }
}

